def _make_fake_moe_model(
    layer_names: list[str], enabled: list[bool], use_dict: bool
) -> nn.Module:
    layers = []
    for flag in enabled:
        layer = nn.Module()
        layer.mlp = _FakeMoE(flag)
        layers.append(layer)
    model = nn.Module()
    model.layers = (
        nn.ModuleDict(dict(zip(layer_names, layers, strict=True)))
        if use_dict
        else nn.ModuleList(layers)
    )
    return model

